const fs = require('fs');
const { Agent } = require('@voltagent/core');
const { XSAIProvider } = require('@voltagent/xsai');
const { z } = require('zod');

const logPath = '/home/user/app/hooks.log';

// Ensure the log file is clean or exists
if (fs.existsSync(logPath)) {
  fs.unlinkSync(logPath);
}

function logHook(message) {
  fs.appendFileSync(logPath, `${message}\n`);
}

const calculate_sum = {
  name: 'calculate_sum',
  description: 'Calculate the sum of two numbers',
  schema: z.object({
    a: z.number(),
    b: z.number(),
  }),
  execute: async ({ a, b }) => {
    return a + b;
  },
};

const provider = new XSAIProvider({
  model: 'gpt-4o-mini',
  apiKey: process.env.OPENAI_API_KEY,
});

const agent = new Agent({
  provider,
  tools: [calculate_sum],
  hooks: {
    onStart: async () => {
      logHook('HOOK: onStart');
    },
    onToolStart: async ({ tool }) => {
      if (tool.name === 'calculate_sum') {
        logHook('HOOK: onToolStart - calculate_sum');
      }
    },
    onToolEnd: async ({ tool }) => {
      if (tool.name === 'calculate_sum') {
        logHook('HOOK: onToolEnd - calculate_sum');
      }
    },
    onEnd: async () => {
      logHook('HOOK: onEnd');
    },
  },
});

async function main() {
  try {
    await agent.generateText({
      prompt: 'Calculate the sum of 15 and 27',
    });
  } catch (error) {
    console.error('Error during agent execution:', error);
  } finally {
    process.exit(0);
  }
}

